import { FEE_BPS, SECONDS_PER_DAY, ACCEPT_WINDOW_SECONDS } from '../constants';
import { usdc } from '../money/usdc';
import type { Bet, Party, Referee } from '../types/bet';
import type { BetId, HexHash, ShortCode, UserId, WalletAddress } from '../types/ids';
import { ZERO_USDC } from '../types/money';

/** Stable, schema-valid ids for fixtures. Real ids are generated by the app, never here. */
export const FIXTURE_IDS = {
  betId: '6f1c2a3e-4b5d-4c6e-8f70-1a2b3c4d5e6f' as BetId,
  shortCode: 'Ab3kZ9xQ' as ShortCode,
  creatorId: '11111111-2222-4333-8444-555555555555' as UserId,
  opponentId: '66666666-7777-4888-9999-000000000000' as UserId,
  refereeId: 'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee' as UserId,
  creatorWallet: 'DimaCreator111111111111111111111111111111' as WalletAddress,
  opponentWallet: 'SashaOpponent1111111111111111111111111111' as WalletAddress,
  termsHash: 'a'.repeat(64) as HexHash,
} as const;

export const FIXTURE_NOW_SECONDS = 1_788_350_400; // 2026-09-02T12:00:00Z

export function makeParty(overrides: Partial<Party> = {}): Party {
  return {
    userId: FIXTURE_IDS.creatorId,
    wallet: FIXTURE_IDS.creatorWallet,
    displayName: 'dima',
    ...overrides,
  };
}

/**
 * A referee who has taken the role. Confirmed by default because that is what most fixtures
 * mean when they say "this bet has a referee" — pass `{ confirmedAtSeconds: null }` for the
 * other kind, which is what a creator's fourth screen actually produces.
 */
export function makeReferee(overrides: Partial<Referee> = {}): Referee {
  return {
    userId: FIXTURE_IDS.refereeId,
    wallet: null,
    displayName: 'anya',
    confirmedAtSeconds: FIXTURE_NOW_SECONDS,
    ...overrides,
  };
}

/** A fully-formed open Bet ("@sasha won't run 10 km before Sunday", $20 vs $20). */
export function makeBet(overrides: Partial<Bet> = {}): Bet {
  const createdAtSeconds = FIXTURE_NOW_SECONDS;
  return {
    id: FIXTURE_IDS.betId,
    shortCode: FIXTURE_IDS.shortCode,
    format: 'bet',
    state: 'open',
    terms: "@sasha won't run 10 km before Sunday.",
    termsHash: FIXTURE_IDS.termsHash,
    stakeCreator: usdc(20),
    stakeOpponent: usdc(20),
    decisionMode: 'mutual',
    creator: makeParty(),
    opponent: null,
    referee: null,
    beneficiary: null,
    createdAtSeconds,
    acceptDeadlineSeconds: createdAtSeconds + ACCEPT_WINDOW_SECONDS,
    deadlineSeconds: createdAtSeconds + 5 * SECONDS_PER_DAY,
    claim: null,
    dispute: null,
    outcome: null,
    feeBps: FEE_BPS,
    chain: 'mock',
    createTx: null,
    acceptTx: null,
    settleTx: null,
    ...overrides,
    ...(overrides.format && overrides.format !== 'bet' && overrides.stakeOpponent === undefined
      ? { stakeOpponent: ZERO_USDC }
      : {}),
  };
}
